adcs_mat3_t ct;
adcs_mat3_t cct;
size_t i;
size_t j;

if ((c == NULL) || (orth == NULL) || (det == NULL)) {
    if (orth != NULL) {
        *orth = INFINITY;
    }
    if (det != NULL) {
        *det = 0.0;
    }
    return ADCS_E_NULL;
}

for (i = 0; i < 3U; i++) {
    for (j = 0; j < 3U; j++) {
        if (!isfinite(c->m[i][j])) {
            *orth = INFINITY;
            *det = 0.0;
            return ADCS_E_NOT_FINITE;
        }
    }
}

ct = adcs_mat3_transpose(c);
cct = adcs_mat3_mul(c, &ct);
*orth = adcs_mat3_frobenius_error_identity(&cct);

*det = adcs_mat3_det(c);

return ADCS_OK;
}

